"""Publish the optimization audit beside the interactive demo."""
from pathlib import Path
import html,json,shutil

R=Path(__file__).resolve().parent;O=R/'optimization';S=R/'site/dist'
def esc(s):return html.escape(str(s))
def pct(v):return f'{100*v:.1f}%'.replace('.',',')

def main():
    r=json.loads((O/'report.json').read_text(encoding='utf-8'));b=json.loads((O/'baseline/results/gcn_0.json').read_text(encoding='utf-8'))
    content=json.loads((R/'presentation/.build/content.json').read_text(encoding='utf-8'))
    old,new=r['summary'][:2];selection=r['selection'];name=selection['selected_config']
    out=S/'optimization';out.mkdir(exist_ok=True)
    for f in ['report.json','selection.json','audit.json','by_timestep.json','validation_learning_curves.png','test_comparison.png']:shutil.copy2(O/f,out/f)
    candidates=[x for x in r['ablations'] if x['seed']==0 and x['graph']]
    labels={'long':'Tăng ngân sách và patience','moderate_weight':'Thêm trọng số lớp 2,33','paper_inspired':'Thêm hidden 100, learning rate 0,001','clipped':'Từ moderate_weight, chặn đặc trưng ở ±5','quantile':'Từ moderate_weight, QuantileTransformer fit trên train'}
    ablation_rows=f"<tr><td>Bản đầu</td><td>180 epoch, patience 30, trọng số 8,19</td><td>179</td><td>{pct(b['validation']['ap'])}</td><td>{pct(b['validation']['f1'])}</td></tr>"+''.join(f"<tr><td>{esc(x['config_name'])}</td><td>{labels[x['config_name']]}</td><td>{x['best_epoch']}</td><td>{pct(x['validation']['ap'])}</td><td>{pct(x['validation']['f1'])}</td></tr>" for x in candidates)
    result_rows=''.join('<tr><td>'+esc(x['name'])+'</td>'+''.join(f"<td>{pct(x[k])} ± {100*x[k+'_std']:.1f}</td>" for k in ['precision','recall','f1','ap'])+'</tr>' for x in r['summary'])
    chosen=next(x for x in candidates if x['config_name']==name)
    quote=content['study'][-1]['sections'][0]['text']
    text=f'''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Vì sao GCN thấp? | Elliptic</title><link rel="stylesheet" href="style.css"><style>.learn img{{width:100%;height:auto;margin:20px 0}}.learn blockquote{{border-left:4px solid #16796f;margin:24px 0;padding:12px 24px;background:#e8eeea}}.learn th,.learn td{{white-space:normal;min-width:100px}}.learn h2{{font-size:30px}}</style></head><body><header><a class="brand" href="index.html">ELLIPTIC LAB</a><nav><a href="index.html#workspace">Demo</a><a href="learn.html">Tài liệu học</a></nav></header><main class="learn"><p class="eyebrow">ĐỐI CHỨNG VÀ TỐI ƯU GCN / BẢN 2</p><h1>{pct(old['f1'])} → {pct(new['f1'])} F1</h1><p>GCN trên cùng tập test lịch sử, trung bình ba seed. Kết quả cũ được giữ nguyên để đối chiếu. Mọi cấu hình, checkpoint và ngưỡng của lần tối ưu được chọn bằng validation.</p>
<section><h2>Đã kiểm tra được điều gì?</h2><ol><li><strong>Ngân sách ban đầu quá ngắn.</strong> Cả ba GCN cũ chọn epoch 179, sát trần 180. Lượt đối chứng giữ nguyên kiến trúc, learning rate, loss và đầu vào; tăng ngân sách lên 1.500 cùng patience 150. Đường AP validation tiếp tục tăng. Phần 180 epoch đầu khớp lại với baseline.</li><li><strong>Cảnh báo nhầm kéo F1 xuống.</strong> Seed 0 cũ có 747 TP và 2.546 FP, Precision chỉ 22,7%. Đây là số đếm từ dự đoán thật, không phải lỗi tính F1.</li><li><strong>Đặc trưng có giá trị cực lớn.</strong> Ngay trên train, trị tuyệt đối lớn nhất sau chuẩn hóa là 321,3; khoảng 0,37% giá trị vượt 5. Cấu hình clipped kiểm tra việc chặn chúng ở ±5 trước truyền tin. Đối chứng bổ sung dùng QuantileTransformer học trên train để đổi theo phân vị sang thang đo gần chuẩn. Đây là các phép thử xử lý đầu vào, không suy đoán tên nghiệp vụ của cột ẩn danh.</li><li><strong>Không phát hiện lỗi nhãn hoặc chia tập.</strong> Unknown không tham gia loss/metrics. Không có cạnh nối các tập. Scaler chỉ fit trên train; không đưa nhãn vào feature.</li></ol></section>
<section><h2>Các đối chứng trên validation</h2><p>Bảng thăm dò dùng seed 0. Thử bốn cấu hình ban đầu và bổ sung một đối chứng chuẩn hóa theo phân vị trước khi đánh giá test lại. Ứng viên có AP cao nhất được lặp ở seed 1 và 2. Quantile đạt AP trung bình 96,22%. Với AP seed 0 của clipped là 88,07%, ngay cả hai seed còn lại đạt 100% thì trung bình tối đa chỉ là 96,02%. Vì thế các lượt lặp dư của clipped được dừng; quyết định vẫn hoàn toàn dựa trên validation. MLP đối chứng dùng đúng cấu hình cuối của GCN, thay graph bằng ma trận đồng nhất.</p><div class="table-wrap"><table><thead><tr><th>Cấu hình</th><th>Thay đổi</th><th>Epoch tốt nhất</th><th>AP validation</th><th>F1 validation</th></tr></thead><tbody>{ablation_rows}</tbody></table></div><p>Cấu hình chọn: <strong>{esc(name)}</strong>. GCN seed 0 chọn epoch {chosen['best_epoch']}, ngưỡng {chosen['threshold']:.6f}. F1 validation dùng ngưỡng tối đa hóa F1 trên chính validation; test luôn dùng lại ngưỡng đó.</p><img src="optimization/validation_learning_curves.png" alt="Đường AP validation theo epoch của năm cấu hình"></section>
<section><h2>Đánh giá lại test sau khi chốt lựa chọn</h2><div class="table-wrap"><table><thead><tr><th>Mô hình</th><th>Precision</th><th>Recall</th><th>F1</th><th>AP</th></tr></thead><tbody>{result_rows}</tbody></table></div><p class="small">Đơn vị %. ± là SD qua ba seed, tính bằng điểm phần trăm; không phải khoảng tin cậy. RF giữ nguyên kết quả. MLP matched đã được huấn luyện lại với thiết lập của GCN mới.</p><img src="optimization/test_comparison.png" alt="F1 trung bình và độ lệch chuẩn qua ba seed"><p><strong>Giới hạn:</strong> test đã được xem ở bản đầu, nên lần này là đánh giá hồi cứu trên test cũ. Không gọi đây là xác nhận trên một holdout mới. Cấu hình và ngưỡng không được chọn theo test.</p></section>
<section><h2>Nói với thầy như thế nào?</h2><blockquote>{esc(quote)}</blockquote><p>RF all nhận 72 đặc trưng tổng hợp hàng xóm do Elliptic cung cấp. Vì vậy nó đã có một dạng thông tin graph. Trong bài báo gốc, Skip-GCN đạt F1 70,5% và RF all đạt 78,8%; RF kết hợp node embeddings đạt 79,6%. Những số này chỉ đặt kết quả vào bối cảnh nghiên cứu, không dùng làm đối chứng ngang hàng vì cách chia và cấu hình của nhóm khác bài báo. <a href="https://arxiv.org/abs/1908.02591">Weber và cộng sự, 2019, Bảng 1</a>.</p><p>Cách đối xứng hóa, nhiễu hàng xóm và thay đổi phân bố là các hướng cần kiểm tra thêm. Thực nghiệm hiện tại chưa tách riêng tác động nhân quả của từng yếu tố này.</p></section>
<section><h2>Mở bằng chứng và tài liệu</h2><p><a href="optimization/report.json">Toàn bộ kết quả JSON</a> · <a href="optimization/selection.json">Lựa chọn chốt trước đánh giá test</a> · <a href="optimization/audit.json">Kiểm tra dữ liệu</a></p><p><a href="downloads/Elliptic_Deep_Graph_26_Slides.pptx">26 slide cập nhật</a> · <a href="downloads/Elliptic_Loi_Thuyet_Trinh_Va_Demo.pdf">Lời thuyết trình</a> · <a href="downloads/Elliptic_Tai_Lieu_Hoc_3_Ngay.pdf">Tài liệu học 3 ngày</a></p><p>Code liên quan: optimize_gcn.py, report_optimization.py, promote_optimized.py. Bản ban đầu được lưu tại optimization/baseline/ trong bộ code.</p></section></main></body></html>'''
    (S/'optimization.html').write_text(text,encoding='utf-8');print('Wrote optimization.html')

if __name__=='__main__':main()
